import React, { useContext, useState } from 'react';
import './Navbar.css';
import logo from '../Assets/logo.png';
import cart_icon from '../Assets/cart_icon.png';
import { Link } from 'react-router-dom';
import { ShopContext } from '../../Context/ShopContext';

export const Navbar = () => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [activeTab, setActiveTab] = useState("shop");
    const { getTotalCartItems } = useContext(ShopContext);

    const toggleMenu = () => setIsMenuOpen(!isMenuOpen);

    return (
        <>
            {/* The Main Floating Trigger Bar */}
            <div className='side-nav-trigger'>
                <div className="nav-logo">
                    <img src={logo} alt="logo" />
                </div>
                
                <div className={`menu-hamburger ${isMenuOpen ? 'open' : ''}`} onClick={toggleMenu}>
                    <span></span>
                    <span></span>
                    <span></span>
                </div>

                <div className="nav-utility">
                    <div className="cart-wrapper">
                        <Link to='/cart'><img src={cart_icon} alt="cart" /></Link>
                        <div className="cart-badge">{getTotalCartItems()}</div>
                    </div>
                </div>
            </div>

            {/* Full Screen Overlay Menu */}
            <div className={`full-menu-overlay ${isMenuOpen ? 'active' : ''}`}>
                <nav className="overlay-nav">
                    <ul>
                        <li onClick={() => {setActiveTab("shop"); toggleMenu();}}>
                            <Link to='/'><span>01.</span> SHOP</Link>
                        </li>
                        <li onClick={() => {setActiveTab("mens"); toggleMenu();}}>
                            <Link to='/mens'><span>02.</span> MEN</Link>
                        </li>
                        <li onClick={() => {setActiveTab("womens"); toggleMenu();}}>
                            <Link to='/womens'><span>03.</span> WOMEN</Link>
                        </li>
                        <li onClick={() => {setActiveTab("kids"); toggleMenu();}}>
                            <Link to='/kids'><span>04.</span> KIDS</Link>
                        </li>
                    </ul>
                </nav>
                <div className="overlay-auth">
                    {localStorage.getItem('auth-token') 
                        ? <button className="auth-btn" onClick={() => { localStorage.removeItem('auth-token'); window.location.replace("/") }}>LOGOUT</button> 
                        : <Link to='/login' onClick={toggleMenu}><button className="auth-btn">LOGIN / REGISTER</button></Link>
                    }
                </div>
            </div>
        </>
    );
};

export default Navbar;
